RATIOS = {
    'social': [(1, 1), (4, 5)],
    'short_video': [(9, 16)],
    'banner': [(16, 9)],
}


def pick_ratios(platform):
    return list(RATIOS.get(platform, []))


def needs_outpaint(src, dst):
    sr = src[0] / src[1]
    dr = dst[0] / dst[1]
    if sr == dr:
        return 'resize-only'
    if dr > sr:
        return 'outpaint'
    return 'crop'

print(pick_ratios('banner'))
